#pragma GCC push_options
#pragma GCC optimize ("O0")

uint32_t __attribute__((weak)) BlendPixels(float percent, uint32_t pxl1rgb, uint32_t pxl2rgb)
    {
    uint32_t rgb ;

    rgb = 0xFF000000 ;
    for (int shift = 0; shift <= 16; shift += 8)
        {
        uint8_t byte1 = (pxl1rgb & 0xFF) ;
        uint8_t byte2 = (pxl2rgb & 0xFF) ;
        uint8_t byte = percent * byte1 + (1.0 - percent) * byte2 ;
        rgb |= byte << shift ;
        pxl1rgb >>= 8 ;
        pxl2rgb >>= 8 ;
        }

    return rgb ;
    }

#pragma GCC pop_options

#define HEADER_ROWS                         48
#define FOOTER_ROWS                         16

#define SLIDER_VMIN                         25
#define SLIDER_VMAX                         180
#define SLIDER_BGCLR                        COLOR_LIGHTGRAY
#define SLIDER_FGCLR                        COLOR_BLACK
#define SLIDER_RPADDING                     5
#define SLIDER_LPADDING                     5
#define SLIDER_HSIZE                        (XPIXELS - SLIDER_LPADDING - SLIDER_RPADDING)
#define SLIDER_VSIZE                        12
#define SLIDER_SSIZE                        SLIDER_VSIZE
#define SLIDER_XMIN                         SLIDER_LPADDING
#define SLIDER_YMIN                         285

#define SCREEN_ADRS                         0xD0000000

#define MIN(a,b)                            ((a) < (b)) ? (a) : (b)

typedef enum {false=0, true=1} BOOL ;

typedef struct
    {
    const float             vmin ;
    const float             vmax ;
    const uint32_t          xmin ;
    const uint32_t          ymin ;
    const uint32_t          width ;
    const uint32_t          height ;
    uint32_t                xpos ;
    float                   percent ;
    } SLIDER ;

// Composite Data Type Declarations ...
typedef uint32_t PIXEL ;
typedef uint32_t RGB ;

#pragma pack(1)
typedef struct
    {
    const uint16_t      type ;              // Magic identifier
    const uint32_t      filesize ;          // File size in bytes
    const uint16_t      reserved1 ;         // Not used
    const uint16_t      reserved2 ;         // Not used
    const uint32_t      offset ;            // Offset to image data in bytes
    const uint32_t      header_size ;       // Header size in bytes
    const uint32_t      width ;             // Width of the image
    const uint32_t      height ;            // Height of image
    const uint16_t      planes ;            // Number of color planes
    const uint16_t      bits ;              // Bits per pixel
    const uint32_t      compression ;       // Compression type unsigned strt, stop ;
    const uint32_t      imagesize ;         // Image size in bytes
    const uint32_t      xresolution ;       // Pixels per meter
    const uint32_t      yresolution ;       // Pixels per meter
    const uint32_t      ncolours ;          // Number of colors
    const uint32_t      importantcolours ;  // Important colors
    const uint32_t      palette[0] ;        // color table (if any) IBGR
    } BMP_HEADER ;
#pragma pack()

// Public fonts defined in run-time library
typedef struct
    {
    const uint8_t *         table ;
    const uint16_t          Width ;
    const uint16_t          Height ;
    } sFONT ;

