int main()
    {
    BMP_HEADER * const bmp1 = (BMP_HEADER *) george_bmp ;
    BMP_HEADER * const bmp2 = (BMP_HEADER *) hillary_bmp ;
    float percent ;

    InitializeHardware(HEADER, "Lab 9E: Image Morphing") ;
    SanityCheck() ;
    InitializeTouchScreen() ;

    percent = slider.percent = 0.5 ;
    InitSlider(&slider) ;
    MorphImages(percent, bmp1, bmp2) ;

    for (;;)
        {
        // Use slider to control morphing
        CheckSlider() ;
        if (slider.percent != percent)
            {
            percent = slider.percent ;
            MorphImages(percent, bmp1, bmp2) ;
            }
        }

    return 0 ;
    }

static void MorphImages(float percent, BMP_HEADER *bmp1, BMP_HEADER *bmp2)
    {
    typedef PIXEL PXLROW[240] ;
    PXLROW * const ppixels = (PXLROW *) 0xD0000000 ;
    int xoff, yoff, row, col, rows, cols ;
    uint8_t *img1, *img2, *pxl1, *pxl2 ;
    PIXEL *ppixel ;

    rows = MIN(bmp1->height, bmp2->height) ;
    cols = MIN(bmp1->width,  bmp2->width) ;

    xoff = (XPIXELS - cols) / 2 ;
    yoff = HEADER_ROWS + (SLIDER_YMIN - HEADER_ROWS - rows) / 2 ;
    pxl1 = (uint8_t *) (bmp1 + 1) + 4*(1 << bmp1->bits) ;
    pxl2 = (uint8_t *) (bmp2 + 1) + 4*(1 << bmp2->bits) ;
    for (row = 0; row < rows; row++)
        {
        img1 = pxl1 + row * ((bmp1->width * sizeof(uint8_t) + 3) & ~0x3) ;
        img2 = pxl2 + row * ((bmp2->width * sizeof(uint8_t) + 3) & ~0x3) ;
        ppixel = ppixels[yoff + rows - row] + xoff ;
        for (col = 0; col < cols; col++)
            {
            *ppixel++ = BlendPixels(percent, bmp1->palette[*img1++], bmp2->palette[*img2++]) ;
            }
        }
    }

static void InitializeTouchScreen(void)
    {
    static char *message[] =
        {
        "If this message remains on",
        "the screen, there is an",
        "initialization problem with",
        "the touch screen. This does",
        "NOT mean that there is a",
        "problem with your code.",
        " ",
        "To correct the problem,",
        "disconnect and reconnect",
        "the power.",
        NULL
        } ;
    char **pp ;
    unsigned x, y ;

    x = 25 ;
    y = 100 ;
    for (pp = message; *pp != NULL; pp++)
        {
        DisplayStringAt(x, y, *pp) ;
        y += 12 ;
        }
    TS_Init() ;
    ClearDisplay() ;
    }

static void InitSlider(SLIDER *slider)
    {
    SetColor(SLIDER_BGCLR) ;
    FillRect(slider->xmin + 1, slider->ymin, slider->width - 1, slider->height) ;
    SetColor(COLOR_RED) ;
    DrawRect(slider->xmin, slider->ymin, slider->width, slider->height) ;
    UpdateSlider(slider, slider->xpos = slider->xmin + slider->percent * slider->width) ;
    }

static void UpdateSlider(SLIDER *slider, uint32_t x)
    {
    static uint32_t bg[SLIDER_SSIZE], fg[SLIDER_SSIZE] ;
    int k, xold, xnew, ypos, yoff ;
    static BOOL init = true ;

    if (init)
        {
        for (k = 0; k < SLIDER_SSIZE; k++)
            {
            bg[k] = SLIDER_BGCLR ;
            fg[k] = SLIDER_FGCLR ;
            }
        init = false ;
        }

    xold = slider->xpos - SLIDER_SSIZE/2 + 1 ;
    xnew = x - SLIDER_SSIZE/2 + 1 ;
    ypos = slider->ymin + 1 ;
    for (yoff = 0; yoff < slider->height - 1; yoff++)
        {
        uint32_t *base = (uint32_t *) SCREEN_ADRS + XPIXELS*ypos++ ;
        memcpy(base + xold, bg, sizeof(bg)) ;
        memcpy(base + xnew, fg, sizeof(fg)) ;
        }
    slider->xpos = x ;
    slider->percent = (float) (x - slider->xmin - SLIDER_SSIZE/2) / (slider->width - SLIDER_SSIZE - 1) ;
    }

static void CheckSlider(void)
    {
    if (TS_Touched()) Adjust(&slider) ;
    }

static void Adjust(SLIDER *slider)
    {
#   define  XFUDGE  0
#   define  YFUDGE  -10
    uint32_t x, y, xmin, xmax ;

    x = TS_GetX() + XFUDGE ;
    y = TS_GetY() + YFUDGE ;

    xmax = slider->xmin + slider->width - SLIDER_SSIZE/2 - 1 ;
    xmin = slider->xmin + SLIDER_SSIZE/2 ;
    if (!Between(slider->ymin, y, slider->ymin + slider->height - 1))   return ;
    if (!Between(slider->xmin, x, slider->xmin + slider->width - 1))    return ;
    if (x < xmin) x = xmin ;
    if (x > xmax) x = xmax ;
    UpdateSlider(slider, x) ;
    }

static int32_t Between(uint32_t min, uint32_t val, uint32_t max)
    {
    return (min <= val && val <= max) ;
    }

static void SanityCheck(void)
    {
    uint32_t rgb1 = GetRandomNumber() ;
    uint32_t rgb2 = GetRandomNumber() ;
    uint32_t rgbi = BlendPixels(0.5, rgb1, rgb2) ;
    uint32_t mine ;
    int shift ;

    __asm(
        "UHADD8 %[dst],%[src1],%[src2]      \n\t"
        : [dst] "=r" (mine)
        : [src1] "r" (rgb1),
          [src2] "r" (rgb2)
    ) ;
    mine |= 0xFF000000 ;

    for (shift = 0; shift <= 24; shift += 8)
        {
        if (((rgbi ^ mine) & 0xFF) != 0x00)
            {
            Error("BlendPixels", "Bits %d-%d (%02X) != %02X", shift+7, shift, rgbi & 0xFF, mine & 0xFF) ;
            }
        rgbi >>= 8 ;
        mine >>= 8 ;
        }

    LEDs(1, 0) ;
    }

static void Error(char *function, char *format, ...)
    {
#   define GFXROW1              54
#   define GFXROWN              215
#   define GFXROWS              (GFXROWN - GFXROW1 + 1)
#   define MAX(a,b)             ((a) > (b) ? (a) : (b))
#   define ERR_FONT             Font12
#   define ERR_BRDR_COLOR       COLOR_BLACK
#   define ERR_BGND_COLOR       COLOR_RED
#   define ERR_FGND_COLOR       COLOR_WHITE
    uint32_t width, row, col, len1, len2 ;
    char line1[100], line2[100] ;
    va_list args ;

    sprintf(line1, "Function %s:", function) ;
    len1 = strlen(line1) ;

    va_start(args, format) ;
    vsprintf(line2, format, args) ;
    va_end(args) ;
    len2 = strlen(line2) ;

    width = ERR_FONT.Width * (MAX(len1, len2) + 2) ;

    col = (XPIXELS - width) / 2 ;
    row = GFXROW1 + GFXROWS / 2 ;

    SetFontSize(&ERR_FONT) ;
    SetColor(ERR_BGND_COLOR) ;
    FillRect(col + 1, row, width - 1, 3*ERR_FONT.Height) ;
    SetColor(ERR_BRDR_COLOR) ;
    DrawRect(col, row, width, 3*ERR_FONT.Height) ;
    row += ERR_FONT.Height/2 ;

    SetForeground(ERR_FGND_COLOR) ;
    SetBackground(ERR_BGND_COLOR) ;
    DisplayStringAt(col + ERR_FONT.Width, row, line1) ;
    row += ERR_FONT.Height ;
    DisplayStringAt(col + ERR_FONT.Width, row, line2) ;

    LEDs(0, 1) ;
    for (;;) ;
    }

static void LEDs(int grn_on, int red_on)
    {
    static uint32_t * const pGPIOG_MODER    = (uint32_t *) 0x40021800 ;
    static uint32_t * const pGPIOG_ODR      = (uint32_t *) 0x40021814 ;
    
    *pGPIOG_MODER |= (1 << 28) | (1 << 26) ;    // output mode
    *pGPIOG_ODR &= ~(3 << 13) ;         // both off
    *pGPIOG_ODR |= (grn_on ? 1 : 0) << 13 ;
    *pGPIOG_ODR |= (red_on ? 1 : 0) << 14 ;
    }

static void SetFontSize(sFONT *Font)
    {
    extern void BSP_LCD_SetFont(sFONT *) ;
    BSP_LCD_SetFont(Font) ;
    }

